const COMPACT_SHORT_TOPIC: Record<string, Record<Exclude<LocaleCode, Lang6>, string>> = {};

function stripDash(raw: string): string {
  return raw.replace(/\u2014/g, '-').replace(/\s+/g, ' ').trim();
}

export function getLocalizedGuideSeedNames(
  seed: { id: string; category: 'venue' | 'occasion' | 'fair' | 'holiday' | 'geo'; name: string; shortName: string; zone: string },
  locale: LocaleCode,
): LocalizedGuideSeedText {
  // 1. Club-specific seeds (g-15..g-40): preserve official Italian brand name on 'it', clean em-dash and IT parens elsewhere
  if (seed.category === 'venue') {
    if (locale === 'it') {
      return {
        name: stripDash(seed.name),
        shortName: stripDash(seed.shortName),
        zone: stripDash(seed.zone),
      };
    }
    const cleanName = CLEAN_15_40_IT_PARENS[seed.id]?.en || stripDash(seed.name);
    const cleanZone = stripDash(seed.zone)
      .replace(/Parco Ippodromo/gi, 'San Siro Hippodrome Park')
      .replace(/20° Piano/gi, '20th Floor')
      .replace(/Piano/gi, 'Floor');
    return {
      name: cleanName,
      shortName: stripDash(seed.shortName),
      zone: cleanZone,
    };
  }

  // 2. Non-venue seeds (g-41..g-116)
  const row = LANG6_NAMES[seed.id];
  if (row) {
    if (locale === 'en' || locale === 'it' || locale === 'es' || locale === 'fr' || locale === 'de' || locale === 'pt') {
      return {
        name: stripDash(row[locale].name),
        shortName: stripDash(row[locale].shortName),
        zone: stripDash(row[locale].zone),
      };
    }
    const catPrefix = COMPACT_CATEGORY_PREFIX[locale]?.[seed.category] || COMPACT_CATEGORY_PREFIX.nl[seed.category];
    const customShort = COMPACT_SHORT_TOPIC[seed.id]?.[locale];
    const baseEn = row.en;
    return {
      name: stripDash(`${catPrefix}: ${baseEn.name}`),
      shortName: stripDash(customShort || baseEn.shortName),
      zone: stripDash(baseEn.zone),
    };
  }

  return {
    name: stripDash(seed.name),
    shortName: stripDash(seed.shortName),
    zone: stripDash(seed.zone),
  };
}

